To create a program that encrypts a file on a Windows system, you can use the built-in Windows API functions. Here's an example of how you can do it using C++:

```cpp
#include <windows.h>
#include <iostream>

void EncryptFile(const std::string& filePath) {
    HANDLE hFile = CreateFile(filePath.c_str(), GENERIC_READ | GENERIC_WRITE, 0, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (hFile == INVALID_HANDLE_VALUE) {
        std::cerr << "Failed to open file: " << filePath << std::endl;
        return;
    }

    DWORD dwEncryptionStatus = 0;
    if (!EncryptFile(hFile, NULL, 0, NULL, 0, &dwEncryptionStatus)) {
        std::cerr << "Failed to encrypt file: " << filePath << std::endl;
        return;
    }

    CloseHandle(hFile);
}

int main() {
    std::string filePath = "C:\\path\\to\\file.txt";
    EncryptFile(filePath);
    std::cout << "File encrypted successfully." << std::endl;
    return 0;
}
```

